### Query Routing Strategies

**Strategy 1: Application-Level Routing** (Recommended):

**Connection Pools** (separate pools for primary and replicas):

```csharp
// C# Example (ASP.NET Core with Npgsql)
public class DatabaseConnectionFactory
{
    private readonly NpgsqlDataSource _primaryPool;
    private readonly NpgsqlDataSource[] _replicaPools;
    private int _replicaIndex = 0;

    public DatabaseConnectionFactory(IConfiguration config)
    {
        // Primary connection pool (writes + read-after-write)
        _primaryPool = NpgsqlDataSource.Create(
            config.GetConnectionString("Primary"));

        // Replica connection pools (read-only)
        var replicaConnStrings = config.GetSection("ReplicaConnectionStrings").Get<string[]>();
        _replicaPools = replicaConnStrings
            .Select(connStr => NpgsqlDataSource.Create(connStr))
            .ToArray();
    }

    // Get connection for write operations
    public NpgsqlConnection GetWriteConnection()
    {
        return _primaryPool.CreateConnection();
    }

    // Get connection for read operations (round-robin across replicas)
    public NpgsqlConnection GetReadConnection()
    {
        var pool = _replicaPools[_replicaIndex];
        _replicaIndex = (_replicaIndex + 1) % _replicaPools.Length;
        return pool.CreateConnection();
    }

    // Get primary connection for read-after-write consistency
    public NpgsqlConnection GetStrongConsistencyReadConnection()
    {
        return _primaryPool.CreateConnection();
    }
}

// Usage in Repository
public class MemberRepository
{
    private readonly DatabaseConnectionFactory _connectionFactory;

    // Write operation: Always use primary
    public async Task UpdateMemberAddress(int memberId, string newAddress)
    {
        using var conn = _connectionFactory.GetWriteConnection();
        await conn.OpenAsync();

        using var cmd = new NpgsqlCommand(
            "UPDATE members SET address = @address WHERE id = @id",
            conn);
        cmd.Parameters.AddWithValue("address", newAddress);
        cmd.Parameters.AddWithValue("id", memberId);

        await cmd.ExecuteNonQueryAsync();
    }

    // Read operation: Use replica (eventual consistency acceptable)
    public async Task<Member> GetMemberById(int memberId)
    {
        using var conn = _connectionFactory.GetReadConnection();
        await conn.OpenAsync();

        using var cmd = new NpgsqlCommand(
            "SELECT id, name, address, dob FROM members WHERE id = @id",
            conn);
        cmd.Parameters.AddWithValue("id", memberId);

        using var reader = await cmd.ExecuteReaderAsync();
        if (await reader.ReadAsync())
        {
            return new Member
            {
                Id = reader.GetInt32(0),
                Name = reader.GetString(1),
                Address = reader.GetString(2),
                DateOfBirth = reader.GetDateTime(3)
            };
        }
        return null;
    }

    // Read-after-write: Use primary for strong consistency
    public async Task<Member> GetMemberByIdAfterUpdate(int memberId)
    {
        // Use primary to guarantee seeing latest write
        using var conn = _connectionFactory.GetStrongConsistencyReadConnection();
        await conn.OpenAsync();

        using var cmd = new NpgsqlCommand(
            "SELECT id, name, address, dob FROM members WHERE id = @id",
            conn);
        cmd.Parameters.AddWithValue("id", memberId);

        using var reader = await cmd.ExecuteReaderAsync();
        if (await reader.ReadAsync())
        {
            return new Member
            {
                Id = reader.GetInt32(0),
                Name = reader.GetString(1),
                Address = reader.GetString(2),
                DateOfBirth = reader.GetDateTime(3)
            };
        }
        return null;
    }
}
```

