**Strategy 2: Geographic Routing** (user location-based):

```csharp
public class GeographicQueryRouter
{
    private readonly DatabaseConnectionFactory _connectionFactory;
    private readonly IHttpContextAccessor _httpContextAccessor;

    public NpgsqlConnection GetReadConnectionByUserLocation()
    {
        var userState = _httpContextAccessor.HttpContext?.Request.Headers["X-User-State"];

        // West Coast states: Route to West US replica
        if (new[] { "CA", "OR", "WA", "NV", "AZ" }.Contains(userState))
        {
            return _connectionFactory.GetReplicaConnection("west-us");
        }

        // East Coast states: Route to East US primary or replica
        return _connectionFactory.GetReplicaConnection("east-us");
    }
}
```

**Strategy 3: Session Stickiness (Read-After-Write Pattern)**:

```csharp
public class SessionAwareQueryRouter
{
    private readonly IHttpContextAccessor _httpContextAccessor;
    private readonly IMemoryCache _cache;
    private readonly DatabaseConnectionFactory _connectionFactory;

    public async Task<NpgsqlConnection> GetReadConnection(int memberId)
    {
        // Check if this session recently wrote this member record
        var sessionId = _httpContextAccessor.HttpContext?.Session.Id;
        var cacheKey = $"recent_write:{sessionId}:{memberId}";

        if (_cache.TryGetValue(cacheKey, out DateTime writeTime))
        {
            // If written within last 5 seconds, route to primary (replication lag buffer)
            if (DateTime.UtcNow - writeTime < TimeSpan.FromSeconds(5))
            {
                return _connectionFactory.GetWriteConnection(); // Primary
            }
        }

        // No recent write, safe to use replica
        return _connectionFactory.GetReadConnection();
    }

    public async Task UpdateMember(int memberId, Member member)
    {
        using var conn = _connectionFactory.GetWriteConnection();
        // ... perform update ...

        // Mark this member as recently written in this session
        var sessionId = _httpContextAccessor.HttpContext?.Session.Id;
        var cacheKey = $"recent_write:{sessionId}:{memberId}";
        _cache.Set(cacheKey, DateTime.UtcNow, TimeSpan.FromSeconds(10));
    }
}
```

