**Step 3.2: Implement Query Router**

```csharp
// DatabaseConnectionFactory.cs
public class DatabaseConnectionFactory : IDatabaseConnectionFactory
{
    private readonly NpgsqlDataSource _primaryDataSource;
    private readonly List<ReplicaDataSource> _replicaDataSources;
    private readonly IConfiguration _configuration;
    private readonly ILogger<DatabaseConnectionFactory> _logger;
    private readonly IMemoryCache _cache;
    private int _replicaRoundRobinIndex = 0;

    public DatabaseConnectionFactory(
        IConfiguration configuration,
        ILogger<DatabaseConnectionFactory> logger,
        IMemoryCache cache)
    {
        _configuration = configuration;
        _logger = logger;
        _cache = cache;

        // Initialize primary connection pool
        var primaryConnString = configuration["DatabaseConnections:Primary:ConnectionString"];
        _primaryDataSource = NpgsqlDataSource.Create(primaryConnString);

        // Initialize replica connection pools
        _replicaDataSources = configuration
            .GetSection("DatabaseConnections:ReadReplicas")
            .Get<List<ReplicaConfig>>()
            .Where(r => r.Enabled)
            .Select(r => new ReplicaDataSource
            {
                Name = r.Name,
                DataSource = NpgsqlDataSource.Create(r.ConnectionString),
                Region = r.Region
            })
            .ToList();

        _logger.LogInformation(
            "Initialized connection factory with 1 primary and {ReplicaCount} replicas",
            _replicaDataSources.Count);
    }

    public async Task<NpgsqlConnection> GetConnectionAsync(
        QueryContext context,
        CancellationToken cancellationToken = default)
    {
        // Writes always go to primary
        if (context.IsWrite)
        {
            return await GetPrimaryConnectionAsync(cancellationToken);
        }

        // Check read-after-write window
        if (context.EntityId.HasValue && IsRecentWrite(context.EntityType, context.EntityId.Value))
        {
            _logger.LogDebug(
                "Routing read to primary due to recent write: {EntityType}:{EntityId}",
                context.EntityType, context.EntityId);
            return await GetPrimaryConnectionAsync(cancellationToken);
        }

        // Check replication lag (circuit breaker)
        if (await IsReplicationLagTooHigh(cancellationToken))
        {
            _logger.LogWarning("Replication lag too high, routing to primary");
            return await GetPrimaryConnectionAsync(cancellationToken);
        }

        // Geographic routing
        if (_configuration.GetValue<bool>("DatabaseConnections:RoutingStrategy:GeographicRoutingEnabled"))
        {
            var userRegion = context.UserRegion;
            var replica = _replicaDataSources.FirstOrDefault(r => r.Region == userRegion);
            if (replica != null)
            {
                _logger.LogDebug("Geographic routing: {UserRegion} → {ReplicaName}", userRegion, replica.Name);
                return await replica.DataSource.OpenConnectionAsync(cancellationToken);
            }
        }

        // Default: Round-robin across replicas
        return await GetReplicaConnectionRoundRobin(cancellationToken);
    }

    private async Task<NpgsqlConnection> GetPrimaryConnectionAsync(CancellationToken cancellationToken)
    {
        return await _primaryDataSource.OpenConnectionAsync(cancellationToken);
    }

    private async Task<NpgsqlConnection> GetReplicaConnectionRoundRobin(CancellationToken cancellationToken)
    {
        if (_replicaDataSources.Count == 0)
        {
            _logger.LogWarning("No replicas available, falling back to primary");
            return await GetPrimaryConnectionAsync(cancellationToken);
        }

        var replica = _replicaDataSources[_replicaRoundRobinIndex];
        _replicaRoundRobinIndex = (_replicaRoundRobinIndex + 1) % _replicaDataSources.Count;

        _logger.LogDebug("Round-robin routing to {ReplicaName}", replica.Name);
        return await replica.DataSource.OpenConnectionAsync(cancellationToken);
    }

    private bool IsRecentWrite(string entityType, int entityId)
    {
        var cacheKey = $"recent_write:{entityType}:{entityId}";
        return _cache.TryGetValue(cacheKey, out _);
    }

    private async Task<bool> IsReplicationLagTooHigh(CancellationToken cancellationToken)
    {
        // Check cached lag value (refreshed every 30s by background service)
        var maxLagSeconds = _configuration.GetValue<int>("DatabaseConnections:RoutingStrategy:MaxReplicationLagSeconds");
        return _cache.TryGetValue("max_replication_lag_seconds", out double lag) && lag > maxLagSeconds;
    }

    public void MarkRecentWrite(string entityType, int entityId)
    {
        var windowSeconds = _configuration.GetValue<int>("DatabaseConnections:RoutingStrategy:ReadAfterWriteWindowSeconds");
        var cacheKey = $"recent_write:{entityType}:{entityId}";
        _cache.Set(cacheKey, DateTime.UtcNow, TimeSpan.FromSeconds(windowSeconds));
    }
}

// QueryContext.cs
public class QueryContext
{
    public bool IsWrite { get; set; }
    public string EntityType { get; set; }
    public int? EntityId { get; set; }
    public string UserRegion { get; set; }  // e.g., "eastus", "westus"
}

// Usage in Repository
public class MemberRepository
{
    private readonly IDatabaseConnectionFactory _connectionFactory;

    public async Task UpdateMemberAddressAsync(int memberId, string newAddress)
    {
        var context = new QueryContext { IsWrite = true };
        using var conn = await _connectionFactory.GetConnectionAsync(context);

        using var cmd = new NpgsqlCommand(
            "UPDATE members SET address = @address WHERE id = @id",
            conn);
        cmd.Parameters.AddWithValue("address", newAddress);
        cmd.Parameters.AddWithValue("id", memberId);

        await cmd.ExecuteNonQueryAsync();

        // Mark as recent write for read-after-write consistency
        _connectionFactory.MarkRecentWrite("Member", memberId);
    }

    public async Task<Member> GetMemberByIdAsync(int memberId, string userRegion)
    {
        var context = new QueryContext
        {
            IsWrite = false,
            EntityType = "Member",
            EntityId = memberId,
            UserRegion = userRegion
        };

        using var conn = await _connectionFactory.GetConnectionAsync(context);

        using var cmd = new NpgsqlCommand(
            "SELECT id, name, address, dob FROM members WHERE id = @id",
            conn);
        cmd.Parameters.AddWithValue("id", memberId);

        using var reader = await cmd.ExecuteReaderAsync();
        if (await reader.ReadAsync())
        {
            return new Member
            {
                Id = reader.GetInt32(0),
                Name = reader.GetString(1),
                Address = reader.GetString(2),
                DateOfBirth = reader.GetDateTime(3)
            };
        }
        return null;
    }
}
```

**Step 3.3: Background Service for Replication Lag Monitoring**

```csharp
// ReplicationLagMonitorService.cs
public class ReplicationLagMonitorService : BackgroundService
{
    private readonly IConfiguration _configuration;
    private readonly IMemoryCache _cache;
    private readonly ILogger<ReplicationLagMonitorService> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                var primaryConnString = _configuration["DatabaseConnections:Primary:ConnectionString"];
                using var conn = new NpgsqlConnection(primaryConnString);
                await conn.OpenAsync(stoppingToken);

                // Query replication lag from primary
                using var cmd = new NpgsqlCommand(@"
                    SELECT
                      MAX(EXTRACT(EPOCH FROM (NOW() - replay_timestamp))) AS max_lag_seconds
                    FROM pg_stat_replication
                    WHERE state = 'streaming'", conn);

                var maxLag = await cmd.ExecuteScalarAsync(stoppingToken);
                if (maxLag != null && maxLag != DBNull.Value)
                {
                    var lagSeconds = Convert.ToDouble(maxLag);
                    _cache.Set("max_replication_lag_seconds", lagSeconds, TimeSpan.FromSeconds(60));

                    _logger.LogInformation("Replication lag: {LagSeconds}s", lagSeconds);

                    // Alert if lag exceeds threshold
                    var threshold = _configuration.GetValue<int>("DatabaseConnections:RoutingStrategy:MaxReplicationLagSeconds");
                    if (lagSeconds > threshold)
                    {
                        _logger.LogWarning(
                            "ALERT: Replication lag {LagSeconds}s exceeds threshold {Threshold}s",
                            lagSeconds, threshold);
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error monitoring replication lag");
            }

            await Task.Delay(TimeSpan.FromSeconds(30), stoppingToken);
        }
    }
}

// Register in Program.cs
builder.Services.AddHostedService<ReplicationLagMonitorService>();
```

