// MemberController.cs
[ApiController]
[Route("api/members")]
public class MemberController : ControllerBase
{
    private readonly IDatabaseConnectionFactory _connectionFactory;
    private readonly ILogger<MemberController> _logger;

    [HttpGet("{id}/eligibility")]
    public async Task<ActionResult<EligibilityResponse>> GetEligibility(int id)
    {
        // Read query: Route to replica (eventual consistency acceptable)
        var context = new QueryContext
        {
            IsWrite = false,
            EntityType = "Member",
            EntityId = id,
            UserRegion = "eastus"
        };

        using var conn = await _connectionFactory.GetConnectionAsync(context);

        using var cmd = new NpgsqlCommand(@"
            SELECT
                m.id,
                m.name,
                m.date_of_birth,
                e.program_type,
                e.coverage_start,
                e.coverage_end
            FROM members m
            JOIN eligibility e ON m.id = e.member_id
            WHERE m.id = @id
              AND e.coverage_end >= CURRENT_DATE
            ORDER BY e.coverage_start DESC
            LIMIT 1", conn);
        cmd.Parameters.AddWithValue("id", id);

        using var reader = await cmd.ExecuteReaderAsync();
        if (await reader.ReadAsync())
        {
            return Ok(new EligibilityResponse
            {
                MemberId = reader.GetInt32(0),
                Name = reader.GetString(1),
                DateOfBirth = reader.GetDateTime(2),
                ProgramType = reader.GetString(3),
                CoverageStart = reader.GetDateTime(4),
                CoverageEnd = reader.GetDateTime(5),
                IsEligible = true
            });
        }

        return NotFound();
    }

    [HttpPost("{id}/address")]
    public async Task<ActionResult> UpdateAddress(int id, [FromBody] AddressUpdateRequest request)
    {
        // Write operation: Always use primary
        var context = new QueryContext { IsWrite = true };
        using var conn = await _connectionFactory.GetConnectionAsync(context);

        using var cmd = new NpgsqlCommand(@"
            UPDATE members
            SET address = @address,
                city = @city,
                state = @state,
                zip = @zip,
                updated_at = CURRENT_TIMESTAMP
            WHERE id = @id", conn);
        cmd.Parameters.AddWithValue("id", id);
        cmd.Parameters.AddWithValue("address", request.Address);
        cmd.Parameters.AddWithValue("city", request.City);
        cmd.Parameters.AddWithValue("state", request.State);
        cmd.Parameters.AddWithValue("zip", request.Zip);

        var rowsAffected = await cmd.ExecuteNonQueryAsync();

        if (rowsAffected == 0)
        {
            return NotFound();
        }

        // Mark recent write for read-after-write consistency
        _connectionFactory.MarkRecentWrite("Member", id);

        return Ok();
    }

    [HttpGet("{id}")]
    public async Task<ActionResult<MemberResponse>> GetMember(int id)
    {
        // Read query, but check for recent write
        var context = new QueryContext
        {
            IsWrite = false,
            EntityType = "Member",
            EntityId = id,
            UserRegion = "eastus"
        };

        // If this member was recently updated (within 5s), route to primary
        using var conn = await _connectionFactory.GetConnectionAsync(context);

        using var cmd = new NpgsqlCommand(@"
            SELECT id, name, address, city, state, zip, date_of_birth
            FROM members
            WHERE id = @id", conn);
        cmd.Parameters.AddWithValue("id", id);

        using var reader = await cmd.ExecuteReaderAsync();
        if (await reader.ReadAsync())
        {
            return Ok(new MemberResponse
            {
                Id = reader.GetInt32(0),
                Name = reader.GetString(1),
                Address = reader.GetString(2),
                City = reader.GetString(3),
                State = reader.GetString(4),
                Zip = reader.GetString(5),
                DateOfBirth = reader.GetDateTime(6)
            });
        }

        return NotFound();
    }
}
```

**Results**:

| Metric | Before Replicas | After Replicas | Improvement |
