```csharp
// GeographicQueryRouter.cs
public class GeographicQueryRouter
{
    private readonly IConfiguration _configuration;
    private readonly IHttpContextAccessor _httpContextAccessor;

    public string GetUserRegion()
    {
        // Extract user state from JWT claims or HTTP header
        var userState = _httpContextAccessor.HttpContext?.User.FindFirst("state")?.Value
            ?? _httpContextAccessor.HttpContext?.Request.Headers["X-User-State"].FirstOrDefault();

        if (string.IsNullOrEmpty(userState))
        {
            return _configuration["GeographicMapping:DEFAULT"];
        }

        // Map state to Azure region
        var regionKey = $"GeographicMapping:{userState}";
        return _configuration[regionKey] ?? _configuration["GeographicMapping:DEFAULT"];
    }
}

// MemberController.cs
[HttpGet("search")]
public async Task<ActionResult<List<MemberSearchResult>>> SearchMembers(
    [FromQuery] string firstName,
    [FromQuery] string lastName,
    [FromQuery] DateTime? dateOfBirth)
{
    // Geographic routing: Route to replica closest to user
    var userRegion = _geographicRouter.GetUserRegion();

    var context = new QueryContext
    {
        IsWrite = false,
        UserRegion = userRegion
    };

    using var conn = await _connectionFactory.GetConnectionAsync(context);

    using var cmd = new NpgsqlCommand(@"
        SELECT id, name, date_of_birth, state
        FROM members
        WHERE first_name ILIKE @firstName
          AND last_name ILIKE @lastName
          AND (@dob IS NULL OR date_of_birth = @dob)
        ORDER BY last_name, first_name
        LIMIT 50", conn);
    cmd.Parameters.AddWithValue("firstName", $"%{firstName}%");
    cmd.Parameters.AddWithValue("lastName", $"%{lastName}%");
    cmd.Parameters.AddWithValue("dob", (object)dateOfBirth ?? DBNull.Value);

    var results = new List<MemberSearchResult>();
    using var reader = await cmd.ExecuteReaderAsync();
    while (await reader.ReadAsync())
    {
        results.Add(new MemberSearchResult
        {
            Id = reader.GetInt32(0),
            Name = reader.GetString(1),
            DateOfBirth = reader.GetDateTime(2),
            State = reader.GetString(3)
        });
    }

    return Ok(results);
}
```

